type Copy = { [K in keyof typeof messages.en]: string }

export function AgentsPage() {
  const copy = useTranslations(messages), notices = useNotices(), cache = useQueryClient()
  const snapshot = useQuery({ queryKey: ['agents'], queryFn: agentsApi.list, retry: false })
  const forbidden = snapshot.error instanceof ApiError && snapshot.error.status === 403
  useQueryErrorNotice(forbidden ? null : snapshot.error, copy.loadError)
  const [defaults, setDefaults] = useState(false), [setupAgent, setSetupAgent] = useState<InstalledAgent | null>(null), [updateJob, setUpdateJob] = useState<{ jobId: string; agent: MarketplaceAgent } | null>(null)
  const refresh = () => cache.invalidateQueries({ queryKey: ['agents'] })
  const install = useMutation({ mutationFn: (agent: MarketplaceAgent) => agentsApi.install(agent.entry_json), onSuccess: (_, agent) => { notices.success(copy.saved); void refresh().then(() => setSetupAgent({ id: agent.id, name: agent.name, version: agent.version, provider_id: '', model_id: '', image_provider_id: '', image_model_id: '', capability_count: 0, is_bundled: false, setup_complete: false, auto_update: false, update_available: false, marketplace_version: '' })) }, onError: (error) => notices.error(error, copy.installFailed) })
  const update = useMutation({ mutationFn: (agent: MarketplaceAgent) => agentsApi.startUpdate(agent.entry_json), onSuccess: (job, agent) => setUpdateJob({ jobId: job.job_id, agent }), onError: (error) => notices.error(error, copy.updateFailed) })
  const check = useMutation({ mutationFn: agentsApi.checkUpdates, onSuccess: () => { notices.success(copy.updated); void refresh() }, onError: (error) => notices.error(error, copy.checkFailed) })
  return <AppPageShell active="agents" width="wide">
    <PageHeader eyebrow={copy.eyebrow} title={copy.title} description={copy.description} actions={<><Button leadingIcon={<Gauge />} onClick={() => setDefaults(true)}>{copy.defaults}</Button><Button leadingIcon={<RefreshCw />} loading={check.isPending} onClick={() => check.mutate()}>{copy.checkUpdates}</Button></>} />
    {snapshot.isPending ? <ManagementLoading /> : forbidden ? <EmptyState icon={<ShieldCheck />} title={copy.forbidden} description={copy.forbiddenBody} /> : snapshot.isError || !snapshot.data ? <EmptyState icon={<AlertTriangle />} title={copy.loadError} action={<Button onClick={() => void snapshot.refetch()}>{copy.retry}</Button>} /> : <div className="final-stack"><ManagementSection title={copy.installed}>{snapshot.data.installed.length ? <OverviewGrid>{snapshot.data.installed.map((agent) => <OverviewCard key={agent.id} icon={<Bot />} status={<StatusBadge tone={!agent.setup_complete || agent.update_available ? 'warning' : 'success'}>{!agent.setup_complete ? copy.setupNeeded : agent.update_available ? copy.updateReady : copy.ready}</StatusBadge>} title={agent.name} description={agent.is_bundled ? copy.bundled : copy.installedVersion.replace('{version}', agent.version || '—')} meta={copy.capabilities.replace('{count}', String(agent.capability_count))} actions={!agent.setup_complete ? <Button size="sm" variant="primary" onClick={() => setSetupAgent(agent)}>{copy.setupNeeded}</Button> : <Link className="selu-ui-button is-secondary is-sm" to="/app/agents/$agentId" params={{ agentId: agent.id }}>{copy.open}</Link>} />)}</OverviewGrid> : <EmptyState icon={<Bot />} title={copy.noAgents} description={copy.noAgentsBody} />}</ManagementSection><ManagementSection title={copy.marketplace} description={copy.marketplaceBody}>{snapshot.data.marketplace_error ? <div className="final-callout">{copy.marketplaceError}</div> : snapshot.data.marketplace.length ? <OverviewGrid>{snapshot.data.marketplace.map((agent) => <OverviewCard key={agent.id} icon={<WandSparkles />} status={agent.average_rating ? <StatusBadge tone="info">★ {agent.average_rating.toFixed(1)}</StatusBadge> : undefined} title={agent.name} description={agent.description} meta={`${copy.version.replace('{version}', agent.version)} · ${agent.author}`} actions={agent.update_available ? <Button size="sm" variant="primary" leadingIcon={<CloudDownload />} loading={update.isPending && update.variables?.id === agent.id} onClick={() => update.mutate(agent)}>{copy.update}</Button> : !agent.is_installed ? <Button size="sm" variant="primary" leadingIcon={<PackagePlus />} loading={install.isPending && install.variables?.id === agent.id} onClick={() => install.mutate(agent)}>{copy.install}</Button> : undefined} />)}</OverviewGrid> : <EmptyState icon={<Sparkles />} title={copy.noMarketplace} />}</ManagementSection></div>}
    {snapshot.data && <DefaultsSheet open={defaults} copy={copy} snapshot={snapshot.data} onClose={() => setDefaults(false)} onSaved={() => { setDefaults(false); notices.success(copy.saved); void refresh() }} />}
    <SetupSheet agent={setupAgent} copy={copy} onClose={() => setSetupAgent(null)} onSaved={() => { setSetupAgent(null); notices.success(copy.setupSaved); void refresh() }} />
    <UpdateSheet state={updateJob} copy={copy} onClose={() => { setUpdateJob(null); void refresh() }} />
  </AppPageShell>
}

export function AgentDetailPage() {
  const { agentId } = useParams({ strict: false }) as { agentId: string }
  const copy = useTranslations(messages), notices = useNotices(), cache = useQueryClient()
  const detail = useQuery({ queryKey: ['agent', agentId], queryFn: () => agentsApi.detail(agentId), retry: false })
  useQueryErrorNotice(detail.error, copy.loadError)
  const [modelSheet, setModelSheet] = useState(false), [runtimeSheet, setRuntimeSheet] = useState(false), [credential, setCredential] = useState<Credential | null>(null), [removeEntry, setRemoveEntry] = useState<{ kind: 'storage' | 'memory'; id: string } | null>(null), [uninstalling, setUninstalling] = useState(false), [resetLearning, setResetLearning] = useState(false)
  const refresh = () => cache.invalidateQueries({ queryKey: ['agent', agentId] })
  const toggleAutomation = useMutation({ mutationFn: (enabled: boolean) => agentsApi.toggleAutomation(agentId, enabled), onSuccess: () => { notices.success(copy.saved); void refresh() }, onError: (error) => notices.error(error, copy.saveFailed) })
  const toggleAuto = useMutation({ mutationFn: (enabled: boolean) => agentsApi.toggleAutoUpdate(agentId, enabled), onSuccess: () => { notices.success(copy.saved); void refresh() }, onError: (error) => notices.error(error, copy.saveFailed) })
  const remove = useMutation({ mutationFn: (entry: { kind: 'storage' | 'memory'; id: string }) => entry.kind === 'storage' ? agentsApi.removeStorage(agentId, entry.id) : agentsApi.removeMemory(agentId, entry.id), onSuccess: () => { setRemoveEntry(null); notices.success(copy.entryRemoved); void refresh() }, onError: (error) => notices.error(error, copy.saveFailed) })
  const uninstall = useMutation({ mutationFn: () => agentsApi.uninstall(agentId), onSuccess: () => { notices.success(copy.uninstalled); window.location.assign(appPath('/app/agents')) }, onError: (error) => notices.error(error, copy.saveFailed) })
  const reset = useMutation({ mutationFn: () => agentsApi.improvement(agentId, 'reset'), onSuccess: () => { setResetLearning(false); notices.success(copy.improvementSaved); void refresh() }, onError: (error) => notices.error(error, copy.saveFailed) })
  return <AppPageShell active="agents" width="wide"><Link className="final-back" to="/app/agents"><ArrowLeft />{copy.back}</Link><PageHeader eyebrow={copy.detailEyebrow} title={detail.data?.name ?? copy.title} description={detail.data ? copy.version.replace('{version}', detail.data.version || '—') : copy.description} actions={detail.data && <><Button leadingIcon={<Gauge />} onClick={() => setRuntimeSheet(true)}>{copy.runtime}</Button><Button leadingIcon={<Bot />} onClick={() => setModelSheet(true)}>{copy.editModel}</Button></>} />
    {detail.isPending ? <ManagementLoading /> : detail.isError || !detail.data ? <EmptyState icon={<AlertTriangle />} title={copy.loadError} action={<Button onClick={() => void detail.refetch()}>{copy.retry}</Button>} /> : <AgentDetailContent copy={copy} detail={detail.data} onRefresh={() => void refresh()} onCredential={setCredential} onRemoveEntry={(kind, id) => setRemoveEntry({ kind, id })} onToggleAutomation={(enabled) => toggleAutomation.mutate(enabled)} onToggleAuto={(enabled) => toggleAuto.mutate(enabled)} onResetLearning={() => setResetLearning(true)} onUninstall={() => setUninstalling(true)} />}
    {detail.data && <><ModelSheet open={modelSheet} copy={copy} agent={detail.data} onClose={() => setModelSheet(false)} onSaved={() => { setModelSheet(false); notices.success(copy.saved); void refresh() }} /><RuntimeSheet open={runtimeSheet} copy={copy} agent={detail.data} onClose={() => setRuntimeSheet(false)} onSaved={() => { setRuntimeSheet(false); notices.success(copy.saved); void refresh() }} /><CredentialSheet credential={credential} agentId={agentId} copy={copy} onClose={() => setCredential(null)} onSaved={() => { setCredential(null); notices.success(copy.secretSaved); void refresh() }} /></>}
    <ConfirmDialog open={Boolean(removeEntry)} title={removeEntry?.kind === 'storage' ? copy.removeStorageTitle : copy.removeMemoryTitle} message={removeEntry?.kind === 'storage' ? copy.removeStorageBody : copy.removeMemoryBody} confirmLabel={copy.remove} cancelLabel={copy.cancel} destructive busy={remove.isPending} onCancel={() => setRemoveEntry(null)} onConfirm={() => removeEntry && remove.mutate(removeEntry)} />
    <ConfirmDialog open={resetLearning} title={copy.resetLearningTitle} message={copy.resetLearningBody} confirmLabel={copy.resetLearning} cancelLabel={copy.cancel} destructive busy={reset.isPending} onCancel={() => setResetLearning(false)} onConfirm={() => reset.mutate()} />
    <ConfirmDialog open={uninstalling} title={copy.uninstallTitle.replace('{name}', detail.data?.name ?? '')} message={copy.uninstallBody} confirmLabel={copy.uninstall} cancelLabel={copy.cancel} destructive busy={uninstall.isPending} onCancel={() => setUninstalling(false)} onConfirm={() => uninstall.mutate()} />
  </AppPageShell>
}

function AgentDetailContent({ copy, detail, onRefresh, onCredential, onRemoveEntry, onToggleAutomation, onToggleAuto, onResetLearning, onUninstall }: { copy: Copy; detail: AgentDetail; onRefresh: () => void; onCredential: (credential: Credential) => void; onRemoveEntry: (kind: 'storage' | 'memory', id: string) => void; onToggleAutomation: (enabled: boolean) => void; onToggleAuto: (enabled: boolean) => void; onResetLearning: () => void; onUninstall: () => void }) {
  const tabs = [{ id: 'overview', label: copy.overview, panel: <OverviewPanel copy={copy} detail={detail} onToggleAutomation={onToggleAutomation} onToggleAuto={onToggleAuto} /> }, { id: 'permissions', label: copy.tools, panel: <PermissionsPanel copy={copy} detail={detail} onRefresh={onRefresh} /> }, { id: 'secrets', label: copy.secrets, panel: <SecretsPanel copy={copy} detail={detail} onCredential={onCredential} onRefresh={onRefresh} /> }, { id: 'storage', label: copy.storage, panel: <EntriesPanel copy={copy} kind="storage" entries={detail.storage} onRemove={(id) => onRemoveEntry('storage', id)} /> }, { id: 'memory', label: copy.memory, panel: <EntriesPanel copy={copy} kind="memory" entries={detail.memory} onRemove={(id) => onRemoveEntry('memory', id)} /> }, { id: 'network', label: copy.network, panel: <NetworkPanel copy={copy} detail={detail} onRefresh={onRefresh} /> }, { id: 'improvement', label: copy.improvement, panel: <ImprovementPanel copy={copy} detail={detail} onRefresh={onRefresh} onReset={onResetLearning} /> }]
  return <div className="final-stack"><div className="final-detail-hero"><div><h2>{detail.name}</h2><p>{detail.provider_id && detail.model_id ? `${detail.provider_id} · ${detail.model_id}` : copy.selectModel}</p></div><div className="final-detail-status"><StatusBadge tone="success">{copy.ready}</StatusBadge>{detail.is_bundled && <StatusBadge>{copy.bundled}</StatusBadge>}</div></div><Tabs label={copy.details} tabs={tabs} /><ManagementSection title={copy.danger} actions={<Button variant="danger" leadingIcon={<Trash2 />} disabled={detail.is_bundled} onClick={onUninstall}>{copy.uninstall}</Button>}><p className="management-muted">{detail.is_bundled ? copy.bundled : copy.uninstallBody}</p></ManagementSection></div>
}

function OverviewPanel({ copy, detail, onToggleAutomation, onToggleAuto }: { copy: Copy; detail: AgentDetail; onToggleAutomation: (enabled: boolean) => void; onToggleAuto: (enabled: boolean) => void }) { const stats = [[detail.overview.capability_count, copy.statsCapabilities], [detail.overview.storage_count, copy.statsStorage], [detail.overview.memory_count, copy.statsMemory], [detail.overview.network_request_count, copy.statsNetwork], [detail.overview.permissions_allow_count, copy.statsAllow], [detail.overview.permissions_ask_count, copy.statsAsk], [detail.overview.permissions_block_count, copy.statsBlock], [`${detail.overview.secrets_set_count}/${detail.overview.secrets_set_count + detail.overview.secrets_missing_count}`, copy.statsSecrets]]; return <div className="final-section-stack"><div className="final-metrics">{stats.map(([value, label]) => <div className="final-metric" key={label}><strong>{value}</strong><span>{label}</span></div>)}</div><ManagementSection title={copy.automation} description={detail.automation.supported ? detail.automation.presets.map((preset) => preset.label).join(' · ') : copy.disabled}><SwitchRow title={copy.automation} description={detail.automation.ready ? copy.automationReady : copy.automationNeedsSetup} checked={detail.automation.enabled} disabled={!detail.automation.supported || !detail.automation.ready} onChange={onToggleAutomation} />{detail.automation.missing_default_pipe && <div className="final-callout">{copy.missingPipe}</div>}{detail.automation.missing_required_credentials && <div className="final-callout">{copy.missingCredentials}</div>}</ManagementSection>{!detail.is_bundled && <ManagementSection title={copy.autoUpdate}><SwitchRow title={copy.autoUpdate} description={copy.version.replace('{version}', detail.version)} checked={detail.auto_update} onChange={onToggleAuto} /></ManagementSection>}<Rating copy={copy} agentId={detail.id} /></div> }

function PermissionsPanel({ copy, detail, onRefresh }: { copy: Copy; detail: AgentDetail; onRefresh: () => void }) { return <div className="final-section-stack">{detail.capabilities.map((capability) => <CapabilityPermissions key={capability.id} copy={copy} agentId={detail.id} capability={capability} onRefresh={onRefresh} />)}<ManagementSection title={copy.overview} description={copy.permissionHint}><ToolList copy={copy} agentId={detail.id} tools={detail.builtin_permissions} onRefresh={onRefresh} /></ManagementSection></div> }
function CapabilityPermissions({ copy, agentId, capability, onRefresh }: { copy: Copy; agentId: string; capability: Capability; onRefresh: () => void }) { const notices = useNotices(); const image = useMutation({ mutationFn: () => agentsApi.downloadImage(agentId, capability.id), onSuccess: () => { notices.success(copy.saved); onRefresh() }, onError: (error) => notices.error(error, copy.saveFailed) }); return <ManagementSection title={capability.id} description={`${copy.resources.replace('{memory}', String(capability.max_memory_mb)).replace('{cpu}', String(capability.max_cpu_percent))} · ${copy.filesystem.replace('{mode}', capability.filesystem)} · ${copy.networkMode.replace('{mode}', capability.effective_network_mode)}`} actions={<><StatusBadge tone={capability.image_status === 'available' ? 'success' : capability.image_status === 'missing' ? 'warning' : 'neutral'}>{capability.image_status === 'available' ? copy.imageReady : capability.image_status === 'missing' ? copy.imageMissing : copy.imageUnknown}</StatusBadge>{capability.image_status === 'missing' && <Button size="sm" loading={image.isPending} onClick={() => image.mutate()}>{copy.downloadImage}</Button>}</>}><ToolList copy={copy} agentId={agentId} tools={capability.tools} onRefresh={onRefresh} /></ManagementSection> }
function ToolList({ copy, agentId, tools, onRefresh }: { copy: Copy; agentId: string; tools: Tool[]; onRefresh: () => void }) { const notices = useNotices(); const change = useMutation({ mutationFn: ({ tool, policy }: { tool: Tool; policy: string }) => agentsApi.setPermission(agentId, { capability_id: tool.capability_id, tool_name: tool.name, policy, scope: 'user' }), onSuccess: () => { notices.success(copy.permissionSaved); onRefresh() }, onError: (error) => notices.error(error, copy.saveFailed) }); const reset = useMutation({ mutationFn: (tool: Tool) => agentsApi.resetPermission(agentId, { capability_id: tool.capability_id, tool_name: tool.name }), onSuccess: () => { notices.success(copy.permissionSaved); onRefresh() }, onError: (error) => notices.error(error, copy.saveFailed) }); return tools.length ? <div className="final-list">{tools.map((tool) => <div className="final-list-row" key={`${tool.capability_id}:${tool.name}`}><div className="final-list-copy"><strong>{tool.display_name}</strong><small>{tool.description}<br />{tool.has_override ? copy.personalOverride : copy.globalDefault.replace('{policy}', policyLabel(copy, tool.global_default))}</small></div><div className="final-list-actions"><Select aria-label={`${copy.permissions}: ${tool.display_name}`} value={tool.policy === 'not set' ? 'block' : tool.policy} disabled={change.isPending} onChange={(event) => change.mutate({ tool, policy: event.target.value })}><option value="allow">{copy.allow}</option><option value="ask">{copy.ask}</option><option value="block">{copy.block}</option></Select>{tool.has_override && <Button size="sm" variant="ghost" loading={reset.isPending && reset.variables?.name === tool.name} onClick={() => reset.mutate(tool)}>{copy.reset}</Button>}</div></div>)}</div> : <p className="management-muted">{copy.noTools}</p> }

function SecretsPanel({ copy, detail, onCredential, onRefresh }: { copy: Copy; detail: AgentDetail; onCredential: (credential: Credential) => void; onRefresh: () => void }) { const notices = useNotices(); const remove = useMutation({ mutationFn: (credential: Credential) => agentsApi.removeCredential(detail.id, credential), onSuccess: () => { notices.success(copy.secretRemoved); onRefresh() }, onError: (error) => notices.error(error, copy.saveFailed) }); const credentials = detail.capabilities.flatMap((capability) => capability.credentials); return credentials.length ? <div className="final-list">{credentials.map((credential) => <div className="final-list-row" key={`${credential.scope}:${credential.capability_id}:${credential.name}`}><div className="final-list-copy"><strong>{credential.name}</strong><small>{credential.description} · {credential.capability_id}</small></div><div className="final-list-actions"><StatusBadge tone={credential.is_set ? 'success' : credential.required ? 'warning' : 'neutral'}>{credential.is_set ? copy.secretSet : copy.secretMissing}</StatusBadge><Button size="sm" onClick={() => onCredential(credential)}>{credential.is_set ? copy.replace : copy.save}</Button>{credential.is_set && <Button size="sm" variant="ghost" loading={remove.isPending} onClick={() => remove.mutate(credential)}>{copy.remove}</Button>}</div></div>)}</div> : <EmptyState icon={<KeyRound />} title={copy.noSecrets} /> }

function EntriesPanel({ copy, kind, entries, onRemove }: { copy: Copy; kind: 'storage' | 'memory'; entries: AgentDetail['storage'] | AgentDetail['memory']; onRemove: (id: string) => void }) { if (!entries.length) return <EmptyState icon={kind === 'storage' ? <Database /> : <Brain />} title={kind === 'storage' ? copy.noStorage : copy.noMemory} />; return <div className="final-list">{entries.map((entry) => { const storage = 'key' in entry; return <div className="final-list-row" key={entry.id}><div className="final-list-copy"><strong>{storage ? entry.key : entry.memory}</strong><small>{storage ? entry.value : `${copy.source}: ${entry.source}${entry.tags ? ` · ${copy.tags}: ${entry.tags}` : ''}`}</small></div><Button size="sm" variant="ghost" onClick={() => onRemove(entry.id)}>{copy.remove}</Button></div> })}</div> }

function NetworkPanel({ copy, detail, onRefresh }: { copy: Copy; detail: AgentDetail; onRefresh: () => void }) { return <div className="final-section-stack">{detail.capabilities.map((capability) => <CapabilityNetwork key={capability.id} copy={copy} agentId={detail.id} capability={capability} onRefresh={onRefresh} />)}<ManagementSection title={copy.recentNetwork}>{detail.network_log.length ? <div className="final-list">{detail.network_log.map((entry, index) => <div className="final-list-row" key={`${entry.created_at}:${index}`}><div className="final-list-copy"><strong>{entry.host}:{entry.port}</strong><small>{entry.capability_id} · {entry.method}</small></div><StatusBadge tone={entry.allowed ? 'success' : 'danger'}>{entry.allowed ? copy.allowed : copy.blocked}</StatusBadge></div>)}</div> : <p className="management-muted">{copy.noNetwork}</p>}</ManagementSection></div> }
function CapabilityNetwork({ copy, agentId, capability, onRefresh }: { copy: Copy; agentId: string; capability: Capability; onRefresh: () => void }) { const notices = useNotices(), [host, setHost] = useState(''), [policy, setPolicy] = useState('allow'); const access = useMutation({ mutationFn: (allowed: boolean) => agentsApi.setNetworkAccess(agentId, capability.id, allowed ? 'allow' : 'deny'), onSuccess: () => { notices.success(copy.saved); onRefresh() }, onError: (error) => notices.error(error, copy.saveFailed) }); const add = useMutation({ mutationFn: () => agentsApi.setNetworkHost(agentId, capability.id, host, policy), onSuccess: () => { setHost(''); notices.success(copy.saved); onRefresh() }, onError: (error) => notices.error(error, copy.saveFailed) }); const remove = useMutation({ mutationFn: (value: string) => agentsApi.removeNetworkHost(agentId, capability.id, value), onSuccess: () => { notices.success(copy.saved); onRefresh() }, onError: (error) => notices.error(error, copy.saveFailed) }); return <ManagementSection title={capability.id} description={copy.networkMode.replace('{mode}', capability.effective_network_mode)}><SwitchRow title={capability.network_access_policy === 'deny' ? copy.networkBlocked : copy.networkAllowed} description={capability.network_access_policy === 'deny' ? copy.blockNetwork : copy.allowNetwork} checked={capability.network_access_policy !== 'deny'} onChange={(next) => access.mutate(next)} /><h3>{copy.hosts}</h3><div className="final-list">{capability.host_policies.map((item) => <div className="final-list-row" key={item.host}><div className="final-list-copy"><strong>{item.host}</strong><small>{item.source === 'custom' ? copy.customRule : copy.defaultRule}</small></div><div className="final-list-actions"><StatusBadge tone={item.policy === 'allow' ? 'success' : 'danger'}>{item.policy === 'allow' ? copy.allowed : copy.blocked}</StatusBadge>{item.removable && <Button size="sm" variant="ghost" loading={remove.isPending && remove.variables === item.host} onClick={() => remove.mutate(item.host)}>{copy.remove}</Button>}</div></div>)}</div><div className="final-inline-fields"><Field label={copy.host}><Input value={host} onChange={(event) => setHost(event.target.value)} placeholder="example.com" /></Field><Field label={copy.policy}><Select value={policy} onChange={(event) => setPolicy(event.target.value)}><option value="allow">{copy.allow}</option><option value="deny">{copy.block}</option></Select></Field><Button loading={add.isPending} disabled={!host.trim()} onClick={() => add.mutate()}>{copy.addHost}</Button></div></ManagementSection> }

function ImprovementPanel({ copy, detail, onRefresh, onReset }: { copy: Copy; detail: AgentDetail; onRefresh: () => void; onReset: () => void }) { const notices = useNotices(); const action = useMutation({ mutationFn: ({ insight, action }: { insight: Insight; action: string }) => agentsApi.improvement(detail.id, action, insight.id), onSuccess: () => { notices.success(copy.improvementSaved); onRefresh() }, onError: (error) => notices.error(error, copy.saveFailed) }); return <ManagementSection title={copy.improvement} description={copy.signals.replace('{count}', String(detail.improvement.signal_count))} actions={<Button size="sm" variant="ghost" onClick={onReset}>{copy.resetLearning}</Button>}>{detail.improvement.insights.length ? <div className="final-list">{detail.improvement.insights.map((insight) => <div className="final-list-row" key={insight.id}><div className="final-list-copy"><strong>{insight.lesson_text}</strong><small>{insight.insight_type} · {copy.confidence.replace('{value}', String(insight.confidence_percent))} · {insight.status}</small></div><div className="final-list-actions"><Button size="sm" onClick={() => action.mutate({ insight, action: insight.status === 'active' ? 'pause' : 'activate' })}>{insight.status === 'active' ? copy.pause : copy.activate}</Button><Button size="sm" variant="ghost" onClick={() => action.mutate({ insight, action: 'reject' })}>{copy.reject}</Button></div></div>)}</div> : <EmptyState icon={<Sparkles />} title={copy.noInsights} />}</ManagementSection> }

function DefaultsSheet({ open, copy, snapshot, onClose, onSaved }: { open: boolean; copy: Copy; snapshot: AgentsSnapshot; onClose: () => void; onSaved: () => void }) { const notices = useNotices(), [provider, setProvider] = useState(snapshot.default_model.provider_id), [model, setModel] = useState(snapshot.default_model.model_id), [temperature, setTemperature] = useState(String(snapshot.default_model.temperature ?? .7)), [imageProvider, setImageProvider] = useState(snapshot.default_image_model.provider_id), [imageModel, setImageModel] = useState(snapshot.default_image_model.model_id); const models = useQuery({ queryKey: ['agent-models', provider], queryFn: () => connectionsApi.models(provider), enabled: Boolean(provider), retry: false }); const imageModels = useQuery({ queryKey: ['agent-models', imageProvider], queryFn: () => connectionsApi.models(imageProvider), enabled: Boolean(imageProvider), retry: false }); useEffect(() => { if (open) { setProvider(snapshot.default_model.provider_id); setModel(snapshot.default_model.model_id); setTemperature(String(snapshot.default_model.temperature ?? .7)); setImageProvider(snapshot.default_image_model.provider_id); setImageModel(snapshot.default_image_model.model_id) } }, [open, snapshot]); const save = useMutation({ mutationFn: () => agentsApi.setDefaults({ provider_id: provider, model_id: model, temperature: Number(temperature), image_provider_id: imageProvider, image_model_id: imageModel }), onSuccess: onSaved, onError: (error) => notices.error(error, copy.saveFailed) }); return <ManagementSheet open={open} title={copy.defaults} description={copy.description} closeLabel={copy.close} onClose={onClose} busy={save.isPending} actions={<><Button onClick={onClose}>{copy.cancel}</Button><Button variant="primary" loading={save.isPending} onClick={() => save.mutate()}>{copy.save}</Button></>}><div className="management-form"><ModelFields copy={copy} providers={snapshot.providers} provider={provider} model={model} models={models.data ?? []} onProvider={(value) => { setProvider(value); setModel('') }} onModel={setModel} /><Field label={copy.temperature}><Input type="number" min="0" max="2" step="0.1" value={temperature} onChange={(event) => setTemperature(event.target.value)} /></Field><h3>{copy.defaultImageModel}</h3><ModelFields copy={copy} providers={snapshot.providers} provider={imageProvider} model={imageModel} models={imageModels.data ?? []} onProvider={(value) => { setImageProvider(value); setImageModel('') }} onModel={setImageModel} optional /></div></ManagementSheet> }
function ModelSheet({ open, copy, agent, onClose, onSaved }: { open: boolean; copy: Copy; agent: AgentDetail; onClose: () => void; onSaved: () => void }) { const notices = useNotices(), providers = useQuery({ queryKey: ['agents'], queryFn: agentsApi.list }), [provider, setProvider] = useState(agent.provider_id), [model, setModel] = useState(agent.model_id), [temperature, setTemperature] = useState(String(agent.temperature)), [imageProvider, setImageProvider] = useState(agent.image_provider_id), [imageModel, setImageModel] = useState(agent.image_model_id); const models = useQuery({ queryKey: ['agent-models', provider], queryFn: () => connectionsApi.models(provider), enabled: Boolean(provider), retry: false }); const imageModels = useQuery({ queryKey: ['agent-models', imageProvider], queryFn: () => connectionsApi.models(imageProvider), enabled: Boolean(imageProvider), retry: false }); useEffect(() => { if (open) { setProvider(agent.provider_id); setModel(agent.model_id); setTemperature(String(agent.temperature)); setImageProvider(agent.image_provider_id); setImageModel(agent.image_model_id) } }, [open, agent]); const save = useMutation({ mutationFn: async () => { await agentsApi.setModel(agent.id, { provider_id: provider, model_id: model, temperature: Number(temperature) }); await agentsApi.setImageModel(agent.id, imageProvider, imageModel) }, onSuccess: onSaved, onError: (error) => notices.error(error, copy.saveFailed) }); return <ManagementSheet open={open} title={copy.editModel} description={agent.name} closeLabel={copy.close} onClose={onClose} busy={save.isPending} actions={<><Button onClick={onClose}>{copy.cancel}</Button><Button variant="primary" loading={save.isPending} disabled={!provider || !model} onClick={() => save.mutate()}>{copy.save}</Button></>}><div className="management-form"><h3>{copy.thinkingModel}</h3><ModelFields copy={copy} providers={providers.data?.providers ?? []} provider={provider} model={model} models={models.data ?? []} onProvider={(value) => { setProvider(value); setModel('') }} onModel={setModel} /><Field label={copy.temperature}><Input type="number" min="0" max="2" step="0.1" value={temperature} onChange={(event) => setTemperature(event.target.value)} /></Field><h3>{copy.imageModel}</h3><ModelFields copy={copy} providers={providers.data?.providers ?? []} provider={imageProvider} model={imageModel} models={imageModels.data ?? []} onProvider={(value) => { setImageProvider(value); setImageModel('') }} onModel={setImageModel} optional /></div></ManagementSheet> }
function ModelFields({ copy, providers, provider, model, models, onProvider, onModel, optional = false }: { copy: Copy; providers: Provider[]; provider: string; model: string; models: Array<{ id: string; name: string }>; onProvider: (value: string) => void; onModel: (value: string) => void; optional?: boolean }) { return <div className="final-form-grid"><Field label={copy.provider} optional={optional ? copy.optional : undefined}><Select value={provider} onChange={(event) => onProvider(event.target.value)}><option value="">—</option>{providers.map((item) => <option key={item.id} value={item.id}>{item.display_name}</option>)}</Select></Field><Field label={copy.model} optional={optional ? copy.optional : undefined}><Select value={model} onChange={(event) => onModel(event.target.value)}><option value="">—</option>{models.map((item) => <option key={item.id} value={item.id}>{item.name}</option>)}</Select></Field></div> }

function RuntimeSheet({ open, copy, agent, onClose, onSaved }: { open: boolean; copy: Copy; agent: AgentDetail; onClose: () => void; onSaved: () => void }) { const notices = useNotices(), [level, setLevel] = useState(agent.runtime.autonomy_level), [advanced, setAdvanced] = useState(agent.runtime.use_advanced_limits), [iterations, setIterations] = useState(String(agent.runtime.max_tool_loop_iterations)), [delegation, setDelegation] = useState(String(agent.runtime.max_delegation_hops)); useEffect(() => { if (open) { setLevel(agent.runtime.autonomy_level); setAdvanced(agent.runtime.use_advanced_limits); setIterations(String(agent.runtime.max_tool_loop_iterations)); setDelegation(String(agent.runtime.max_delegation_hops)) } }, [open, agent]); const save = useMutation({ mutationFn: () => agentsApi.setRuntime(agent.id, { autonomy_level: level, use_advanced_limits: advanced, max_tool_loop_iterations: Number(iterations), max_delegation_hops: Number(delegation) }), onSuccess: onSaved, onError: (error) => notices.error(error, copy.saveFailed) }); return <ManagementSheet open={open} title={copy.runtime} description={copy.runtimeBody} closeLabel={copy.close} onClose={onClose} busy={save.isPending} actions={<><Button onClick={onClose}>{copy.cancel}</Button><Button variant="primary" loading={save.isPending} onClick={() => save.mutate()}>{copy.save}</Button></>}><div className="management-form"><Field label={copy.runtime}><Select value={level} onChange={(event) => setLevel(event.target.value)}><option value="low">{copy.low}</option><option value="medium">{copy.medium}</option><option value="high">{copy.high}</option></Select></Field><SwitchRow title={copy.advancedLimits} description={copy.runtimeBody} checked={advanced} onChange={setAdvanced} />{advanced && <div className="final-form-grid"><Field label={copy.iterations}><Input type="number" min="0" value={iterations} onChange={(event) => setIterations(event.target.value)} /></Field><Field label={copy.delegation}><Input type="number" min="0" value={delegation} onChange={(event) => setDelegation(event.target.value)} /></Field></div>}</div></ManagementSheet> }
function CredentialSheet({ credential, agentId, copy, onClose, onSaved }: { credential: Credential | null; agentId: string; copy: Copy; onClose: () => void; onSaved: () => void }) { const notices = useNotices(), [value, setValue] = useState(''); useEffect(() => setValue(''), [credential]); const save = useMutation({ mutationFn: () => agentsApi.setCredential(agentId, { capability_id: credential!.capability_id, credential_name: credential!.name, scope: credential!.scope, value }), onSuccess: onSaved, onError: (error) => notices.error(error, copy.saveFailed) }); return <ManagementSheet open={Boolean(credential)} title={credential?.name ?? copy.secrets} description={credential?.description} closeLabel={copy.close} onClose={onClose} busy={save.isPending} actions={<><Button onClick={onClose}>{copy.cancel}</Button><Button variant="primary" loading={save.isPending} disabled={!value} onClick={() => save.mutate()}>{copy.save}</Button></>}><Field label={copy.secretValue} hint={copy.secretHint}><SecretField value={value} onChange={(event) => setValue(event.target.value)} autoComplete="off" showLabel={copy.show} hideLabel={copy.hide} /></Field></ManagementSheet> }

function SetupSheet({ agent, copy, onClose, onSaved }: { agent: InstalledAgent | null; copy: Copy; onClose: () => void; onSaved: () => void }) { const notices = useNotices(); const setup = useQuery({ queryKey: ['agent-setup', agent?.id], queryFn: () => agentsApi.setup(agent!.id), enabled: Boolean(agent), retry: false }); const [values, setValues] = useState<Record<string, string>>({}), [policies, setPolicies] = useState<Record<string, string>>({}), [tested, setTested] = useState<Record<string, boolean>>({}); useEffect(() => { if (setup.data) { setValues(Object.fromEntries(setup.data.steps.map((step) => [`step_${step.id}`, step.default_value]))); setPolicies(Object.fromEntries(setup.data.permissions.map((permission) => [permission.key, permission.recommended]))); setTested({}) } }, [setup.data]); const complete = useMutation({ mutationFn: () => { const payload = { ...values }; setup.data?.permissions.forEach((permission) => { payload[`policy_cap_${permission.key}`] = permission.capability_id; payload[`policy_tool_${permission.key}`] = permission.tool_name; payload[`policy_val_${permission.key}`] = policies[permission.key] ?? permission.recommended }); return agentsApi.completeSetup(agent!.id, payload) }, onSuccess: onSaved, onError: (error) => notices.error(error, copy.saveFailed) }); const test = useMutation({ mutationFn: (step: string) => agentsApi.testSetup(agent!.id, step, values), onSuccess: (result, step) => setTested((current) => ({ ...current, [step]: result.ok })), onError: (_, step) => setTested((current) => ({ ...current, [step]: false })) }); return <ManagementSheet open={Boolean(agent)} title={copy.setupTitle.replace('{name}', setup.data?.agent_name ?? agent?.name ?? '')} description={copy.setupBody} closeLabel={copy.close} onClose={onClose} busy={complete.isPending} actions={<><Button onClick={onClose}>{copy.cancel}</Button><Button variant="primary" loading={complete.isPending} onClick={() => complete.mutate()}>{copy.completeSetup}</Button></>} >{setup.isPending ? <ManagementLoading cards={2} /> : setup.isError || !setup.data ? <EmptyState icon={<AlertTriangle />} title={copy.loadError} /> : <div className="management-form">{setup.data.discovery_warning && <div className="final-callout">{copy.discoveryWarning}</div>}{setup.data.steps.map((step) => step.kind === 'input' ? <Field key={step.id} label={step.label} hint={step.description}><SecretField value={values[`step_${step.id}`] ?? ''} onChange={(event) => setValues((current) => ({ ...current, [`step_${step.id}`]: event.target.value }))} autoComplete="off" showLabel={copy.show} hideLabel={copy.hide} /></Field> : <div className="final-list-row" key={step.id}><div className="final-list-copy"><strong>{step.label}</strong><small>{step.description}</small></div><div className="final-list-actions">{tested[step.id] !== undefined && <StatusBadge tone={tested[step.id] ? 'success' : 'danger'}>{tested[step.id] ? copy.testPassed : copy.testFailed}</StatusBadge>}<Button size="sm" loading={test.isPending && test.variables === step.id} onClick={() => test.mutate(step.id)}>{copy.testConnection}</Button></div></div>)}<h3>{copy.permissions}</h3><p className="management-muted">{copy.permissionHint}</p>{setup.data.permissions.map((permission) => <div className="final-list-row" key={permission.key}><div className="final-list-copy"><strong>{permission.display_name}</strong><small>{permission.description}<br />{copy.recommended.replace('{policy}', policyLabel(copy, permission.recommended))}</small></div><Select value={policies[permission.key] ?? permission.recommended} onChange={(event) => setPolicies((current) => ({ ...current, [permission.key]: event.target.value }))}><option value="allow">{copy.allow}</option><option value="ask">{copy.ask}</option><option value="block">{copy.block}</option></Select></div>)}</div>}</ManagementSheet> }

function UpdateSheet({ state, copy, onClose }: { state: { jobId: string; agent: MarketplaceAgent } | null; copy: Copy; onClose: () => void }) { const job = useQuery({ queryKey: ['agent-update', state?.jobId], queryFn: () => agentsApi.updateStatus(state!.jobId), enabled: Boolean(state), refetchInterval: (query) => query.state.data?.done ? false : 1_000 }); useEffect(() => { if (job.data?.done && job.data.success) { const timer = window.setTimeout(onClose, 1_200); return () => window.clearTimeout(timer) } }, [job.data, onClose]); return <ManagementSheet open={Boolean(state)} title={copy.updateProgress.replace('{name}', state?.agent.name ?? '')} description={job.data ? updateMessage(copy, job.data) : copy.updatePreparing} closeLabel={copy.close} onClose={job.data?.done ? onClose : () => undefined} busy={!job.data?.done}><div className="final-section-stack"><div className="final-progress" role="progressbar" aria-valuemin={0} aria-valuemax={100} aria-valuenow={job.data?.progress ?? 5}><span style={{ width: `${job.data?.progress ?? 5}%` }} /></div>{job.data?.done && <StatusBadge tone={job.data.success ? 'success' : 'danger'}>{job.data.success ? copy.updated : copy.updateFailed}</StatusBadge>}</div></ManagementSheet> }
function Rating({ copy, agentId }: { copy: Copy; agentId: string }) { const notices = useNotices(); const rate = useMutation({ mutationFn: (rating: number) => agentsApi.rate(agentId, rating), onSuccess: () => notices.success(copy.ratingSaved), onError: (error) => notices.error(error, copy.saveFailed) }); return <ManagementSection title={copy.rating}><div className="final-actions">{[1, 2, 3, 4, 5].map((value) => <Button key={value} size="sm" variant="ghost" leadingIcon={<Star />} onClick={() => rate.mutate(value)}>{value}</Button>)}</div></ManagementSection> }
function SwitchRow({ title, description, checked, disabled = false, onChange }: { title: string; description: string; checked: boolean; disabled?: boolean; onChange: (checked: boolean) => void }) { return <div className="final-switch-row"><span><strong>{title}</strong><small>{description}</small></span><button type="button" role="switch" className="final-switch" aria-checked={checked} aria-label={title} disabled={disabled} onClick={() => onChange(!checked)} /></div> }
function policyLabel(copy: Copy, policy: string) { return policy === 'allow' ? copy.allow : policy === 'ask' ? copy.ask : copy.block }
function updateMessage(copy: Copy, job: UpdateJob) { if (job.done) return job.success ? copy.updated : copy.updateFailed; if (job.progress >= 90) return copy.updateFinishing; if (job.progress >= 20) return copy.updateDownloading; return copy.updatePreparing }
